// The comparison's results, as accuracy/REPORT.md (for people) and
// accuracy/summary.json (for the manual, ADR 0059). Both are generated by
// `npm run accuracy:report` and checked to be current by report.test.ts.
import { BRIGHT_SHARE, compareReference, NEAR_M, summarize, type SurfaceSummary } from './compare';
import { IES_FILES, REFERENCES } from './inputs';

/** One reference room's results. */
export interface RoomSummary {
  readonly name: string;
  readonly description: string;
  readonly radianceRelease: string;
  readonly points: number;
  readonly surfaces: readonly SurfaceSummary[];
}

/** Every reference room's results, with the thresholds they were judged by. */
export interface AccuracySummary {
  readonly brightShare: number;
  readonly nearM: number;
  readonly rooms: readonly RoomSummary[];
}

/** Compares every reference room and summarises it. */
export function accuracySummary(): AccuracySummary {
  const rooms = Object.entries(REFERENCES).map(([name, reference]) => {
    const points = compareReference(reference, IES_FILES);
    const origins = reference.room.luminaires.map((luminaire) => luminaire.origin);
    return {
      name,
      description: reference.room.description,
      radianceRelease: reference.radiance.release,
      points: points.length,
      surfaces: summarize(points, origins),
    };
  });
  return { brightShare: BRIGHT_SHARE, nearM: NEAR_M, rooms };
}

const percent = (value: number) => `${(value * 100).toFixed(2)} %`;
const lux = (value: number) => value.toFixed(1);

/** The summary as accuracy/REPORT.md. */
export function reportMarkdown(summary: AccuracySummary): string {
  const lines: string[] = [
    '# Accuracy: Lux Studio against Radiance',
    '',
    'Generated by `npm run accuracy:report` from `accuracy/references` (ADR 0058). Direct',
    'light only, as installed (no maintenance factor). "Bright" points have at least',
    `${summary.brightShare * 100} % of the room's brightest point; "near" ones are within ${summary.nearM} m of a luminaire.`,
    '',
  ];
  for (const room of summary.rooms) {
    lines.push(
      `## ${room.name}`,
      '',
      room.description,
      '',
      `Radiance ${room.radianceRelease}, ${room.points} points.`,
      '',
      '| Surface | Points | Radiance Ē (lx) | Lux Studio Ē (lx) | Ē difference | Worst bright point, far | Worst bright point, near |',
      '|---|---|---|---|---|---|---|',
    );
    for (const surface of room.surfaces) {
      lines.push(
        `| ${surface.surface} | ${surface.points} | ${lux(surface.radianceAverageLx)} | ` +
          `${lux(surface.oursAverageLx)} | ${percent(surface.averageError)} | ` +
          `${surface.worstFar > 0 ? percent(surface.worstFar) : '–'} | ` +
          `${surface.worstNear > 0 ? percent(surface.worstNear) : '–'} |`,
      );
    }
    lines.push('');
  }
  return `${lines.join('\n').trimEnd()}\n`;
}

/** The summary as accuracy/summary.json, rounded so it changes only when the results do. */
export function summaryJson(summary: AccuracySummary): string {
  const round = (value: number, digits: number) => Number(value.toFixed(digits));
  const rounded = {
    ...summary,
    rooms: summary.rooms.map((room) => ({
      ...room,
      surfaces: room.surfaces.map((surface) => ({
        ...surface,
        radianceAverageLx: round(surface.radianceAverageLx, 2),
        oursAverageLx: round(surface.oursAverageLx, 2),
        averageError: round(surface.averageError, 5),
        worstFar: round(surface.worstFar, 5),
        worstNear: round(surface.worstNear, 5),
      })),
    })),
  };
  return `${JSON.stringify(rounded, null, 2)}\n`;
}
